:root {
  --bg: #050b12;
  --bg-2: #101d28;
  --panel: rgba(12, 21, 29, 0.82);
  --panel-strong: rgba(17, 28, 37, 0.96);
  --line: rgba(157, 187, 196, 0.25);
  --line-strong: rgba(157, 187, 196, 0.5);
  --track: #1d2a33;
  --track-2: #0c1317;
  --rail: #d8dde3;
  --signal-green: #70ff88;
  --signal-amber: #ffce5d;
  --signal-red: #ff5c6d;
  --primary: #7feaff;
  --primary-2: #6cf6b3;
  --warning: #ffbd59;
  --danger: #ff6d78;
  --text: #ecf8ff;
  --muted: #a3bdc7;
  --shadow: rgba(0, 0, 0, 0.45);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  background: radial-gradient(circle at top, rgba(63, 101, 131, 0.45), transparent 25%), linear-gradient(180deg, var(--bg), #0b1a22 28%, #070d12 100%);
  color: var(--text);
  overscroll-behavior: none;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: stretch;
  justify-content: center;
}

button {
  font: inherit;
}

.game-shell {
  width: min(100vw, 1200px);
  min-height: 100vh;
  padding: calc(16px + var(--safe-top)) 14px calc(18px + var(--safe-bottom));
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  gap: 10px;
}

.topbar,
.cab-panel,
.statusbar {
  background: rgba(10, 17, 22, 0.7);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: 0 12px 34px var(--shadow);
  backdrop-filter: blur(10px);
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
  text-decoration: none;
  font-weight: 800;
  letter-spacing: 0.12em;
  font-size: clamp(0.78rem, 2vw, 1.05rem);
}

.brand span {
  white-space: nowrap;
}

.brand-mark {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba(127, 234, 255, 0.28), rgba(127, 234, 255, 0.12));
  border: 1px solid rgba(127, 234, 255, 0.4);
  color: var(--primary);
  font-size: 0.8rem;
}

.brand-light {
  color: var(--primary);
}

.edition {
  font-size: 0.62rem;
  letter-spacing: 0.15em;
  opacity: 0.8;
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.route-chip,
.hint-pill,
.toast,
.signal-card,
.objective-card,
.speed-card,
.control-heading,
.route-stats,
.modal-kicker,
.modal-foot,
.statusbar,
.direction-state {
  letter-spacing: 0.04em;
}

.route-chip {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: rgba(17, 28, 37, 0.7);
  border: 1px solid rgba(117, 164, 179, 0.28);
  padding: 8px 12px;
  border-radius: 999px;
  color: var(--muted);
  font-size: 0.63rem;
  text-transform: uppercase;
}

.chip-divider {
  opacity: 0.5;
}

.live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--signal-green);
  box-shadow: 0 0 10px rgba(112, 255, 136, 0.7);
  display: inline-block;
}

.icon-button,
.primary-button,
.notch-button,
.direction-button,
.horn-button,
.reset-button {
  border: none;
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease, box-shadow 0.15s ease;
}

.icon-button:active,
.primary-button:active,
.notch-button:active,
.direction-button:active,
.horn-button:active,
.reset-button:active {
  transform: scale(0.97);
}

.icon-button {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: rgba(19, 33, 46, 0.85);
  border: 1px solid rgba(147, 182, 196, 0.24);
  color: var(--text);
  font-size: 1.1rem;
}

.view {
  position: relative;
  min-height: 0;
  border-radius: 28px;
  overflow: hidden;
  border: 1px solid rgba(157, 187, 196, 0.2);
  background: linear-gradient(180deg, #0c1218 0%, #101c27 28%, #0b1117 100%);
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: linear-gradient(180deg, #0f1a22, #0a0f14 55%, #081018 100%);
}

.scene-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(circle at center, transparent 52%, rgba(3, 8, 12, 0.2) 100%);
}

.scene-topline,
.scene-bottomline {
  position: absolute;
  left: 16px;
  right: 16px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  z-index: 2;
}

.scene-topline {
  top: 14px;
  gap: 14px;
}

.scene-bottomline {
  bottom: 14px;
  align-items: flex-end;
  gap: 12px;
}

.objective-card,
.signal-card,
.speed-card {
  background: rgba(7, 13, 20, 0.6);
  border: 1px solid rgba(165, 191, 202, 0.18);
  border-radius: 18px;
  backdrop-filter: blur(8px);
}

.objective-card {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 150px;
}

.eyebrow {
  display: inline-block;
  color: var(--muted);
  font-size: 0.58rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.objective-card strong,
.signal-card strong,
.route-stats strong {
  font-size: clamp(1rem, 2vw, 1.3rem);
  font-weight: 700;
}

.distance-line {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 0.72rem;
  text-transform: uppercase;
}

.station-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  display: inline-block;
  background: var(--primary);
  box-shadow: 0 0 12px rgba(127, 234, 255, 0.7);
}

.signal-card {
  padding: 12px 14px;
  min-width: 150px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.signal-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.signal-lamp {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
  background: #3a4a51;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.2);
}

.signal-lamp.green {
  background: var(--signal-green);
  box-shadow: 0 0 18px rgba(112, 255, 136, 0.7), inset 0 0 0 1px rgba(255,255,255,.2);
}

.signal-lamp.amber {
  background: var(--signal-amber);
  box-shadow: 0 0 18px rgba(255,206,93,0.7), inset 0 0 0 1px rgba(255,255,255,.2);
}

.signal-lamp.red {
  background: var(--signal-red);
  box-shadow: 0 0 18px rgba(255,92,109,0.7), inset 0 0 0 1px rgba(255,255,255,.2);
}

.signal-note,
.muted,
.control-caption,
.modal-foot,
.key-help {
  color: var(--muted);
}

.signal-note {
  font-size: 0.66rem;
  text-transform: uppercase;
}

.speed-card {
  padding: 12px 12px 10px;
  min-width: 210px;
  background: rgba(8, 15, 19, 0.72);
}

.speed-number {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  font-weight: 800;
  font-size: clamp(1.5rem, 5vw, 2.5rem);
  line-height: 1;
}

.speed-number small {
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  color: var(--muted);
  margin-bottom: 5px;
  text-transform: uppercase;
}

.speed-meta {
  margin-top: 6px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.speed-track {
  position: relative;
  height: 10px;
  width: 100%;
  background: rgba(157, 187, 196, 0.18);
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid rgba(157, 187, 196, 0.12);
}

.speed-track i {
  position: absolute;
  inset: 0 auto 0 0;
  width: 0%;
  background: linear-gradient(90deg, var(--primary), var(--primary-2));
  border-radius: inherit;
}

.speed-track b {
  position: absolute;
  left: 60%;
  top: 50%;
  width: 4px;
  height: 18px;
  transform: translate(-50%, -50%);
  background: #fff7d6;
  border-radius: 999px;
  box-shadow: 0 0 12px rgba(255,255,255,0.4);
}

.track-end {
  color: var(--muted);
}

.hint-pill {
  align-self: flex-end;
  background: rgba(7, 12, 16, 0.6);
  border: 1px solid rgba(154, 184, 196, 0.2);
  color: var(--text);
  border-radius: 999px;
  padding: 10px 14px;
  font-size: 0.62rem;
  text-transform: uppercase;
}

.cab-panel {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1.4fr) minmax(0, 1.2fr) auto;
  gap: 14px;
  padding: 12px 14px;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.control-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.control-heading strong {
  display: block;
  margin-top: 2px;
}

.notch-value {
  color: var(--primary);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.notch-value small {
  color: var(--muted);
  font-size: 0.7rem;
}

.notch-control {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 44px;
  align-items: center;
  gap: 10px;
}

.notch-button {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: rgba(16, 31, 41, 0.92);
  border: 1px solid rgba(157, 187, 196, 0.2);
  color: var(--text);
  font-size: 1.8rem;
  line-height: 1;
}

.notches,
.brake-notches {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  position: relative;
  padding: 4px;
  background: rgba(12, 20, 26, 0.9);
  border: 1px solid rgba(157, 187, 196, 0.12);
  border-radius: 14px;
}

.notches span,
.brake-notches span {
  height: 26px;
  border-radius: 9px;
  background: rgba(157, 187, 196, 0.12);
  border: 1px solid rgba(157, 187, 196, 0.08);
}

.notches span.active,
.brake-notches span.active {
  background: linear-gradient(180deg, rgba(127, 234, 255, 0.75), rgba(108, 246, 179, 0.65));
  border-color: rgba(127, 234, 255, 0.4);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.15), 0 0 14px rgba(127, 234, 255, 0.22);
}

.control-caption {
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.direction-group {
  justify-content: center;
}

.direction-buttons {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 8px;
  align-items: center;
}

.direction-button {
  background: rgba(17, 28, 37, 0.9);
  border: 1px solid rgba(157, 187, 196, 0.18);
  color: var(--text);
  border-radius: 16px;
  min-height: 56px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  font-size: 0.9rem;
}

.direction-button span {
  font-size: 1.4rem;
  line-height: 1;
}

.direction-button small {
  letter-spacing: 0.18em;
  text-transform: uppercase;
  opacity: 0.8;
}

.direction-button.active {
  background: rgba(127, 234, 255, 0.08);
  border-color: rgba(127, 234, 255, 0.35);
  box-shadow: inset 0 0 0 1px rgba(127, 234, 255, 0.14);
}

.direction-state {
  padding: 10px 12px;
  background: rgba(30, 40, 47, 0.8);
  border: 1px solid rgba(157, 187, 196, 0.12);
  border-radius: 12px;
  font-size: 0.7rem;
  text-align: center;
  text-transform: uppercase;
  color: var(--text);
}

.utility-group {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.horn-button,
.reset-button {
  border-radius: 16px;
  min-height: 58px;
}

.horn-button {
  min-width: 110px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: linear-gradient(180deg, rgba(109, 149, 163, 0.26), rgba(14, 25, 33, 0.9));
  border: 1px solid rgba(157, 187, 196, 0.18);
  color: var(--text);
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.horn-icon {
  font-size: 1.2rem;
}

.horn-button kbd,
.key-help kbd {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(157, 187, 196, 0.2);
  border-radius: 7px;
  padding: 2px 6px;
  font-size: 0.56rem;
  letter-spacing: 0.1em;
}

.reset-button {
  width: 58px;
  background: rgba(14, 25, 33, 0.9);
  border: 1px solid rgba(157, 187, 196, 0.18);
  color: var(--text);
  font-size: 1.5rem;
}

.statusbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 14px;
  color: var(--muted);
  font-size: 0.62rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.statusbar span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.status-led {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--signal-green);
  box-shadow: 0 0 10px rgba(112,255,136,0.65);
}

.key-help {
  white-space: nowrap;
}

#scoreReadout b {
  color: var(--text);
}

.modal-layer {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(2, 5, 8, 0.38);
  backdrop-filter: blur(8px);
  z-index: 5;
}

.modal-card {
  width: min(92%, 620px);
  background: rgba(6, 14, 20, 0.84);
  border: 1px solid rgba(157, 187, 196, 0.2);
  border-radius: 28px;
  padding: 22px 20px 18px;
  box-shadow: 0 16px 48px rgba(0,0,0,0.42);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.modal-kicker {
  font-size: 0.62rem;
  color: var(--muted);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.hero-train {
  position: relative;
  height: 90px;
  margin-top: 4px;
  overflow: hidden;
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(91, 121, 138, 0.18), rgba(19, 30, 35, 0.2));
  border: 1px solid rgba(157, 187, 196, 0.08);
}

.sun-disc {
  position: absolute;
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, rgba(255, 250, 222, 0.95), rgba(255, 203, 89, 0.72), rgba(255, 203, 89, 0.12));
  right: 20px;
  top: 12px;
  box-shadow: 0 0 34px rgba(255, 210, 107, 0.58);
}

.rail-line {
  position: absolute;
  left: -10%;
  right: -10%;
  height: 3px;
  background: linear-gradient(90deg, rgba(132, 144, 153, 0.35), rgba(216, 221, 227, 0.55), rgba(132, 144, 153, 0.35));
  border-radius: 999px;
}

.rail-one {
  bottom: 26px;
}

